        std::unique_lock lock{ m_mutex };
        m_notFull.wait(lock, [this] { return m_items.size() < m_capacity || m_closed; });
        if (m_closed) return;
        m_items.push(std::move(value));
        m_notEmpty.notify_one();
    }

